import{_ as t,o as r,c as e,a6 as n}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"收尾 · 决策树与常见坑","description":"用一张「什么页面选什么渲染 + 缓存策略」的决策树，和一份贯穿全专栏的「新手十大坑」清单，把 SSR 从入门到精通的全貌收拢。","frontmatter":{"title":"收尾 · 决策树与常见坑","description":"用一张「什么页面选什么渲染 + 缓存策略」的决策树，和一份贯穿全专栏的「新手十大坑」清单，把 SSR 从入门到精通的全貌收拢。","source":"https://daiw.org/manual/ssr/recap"},"headers":[],"relativePath":"manual/computer-programming/ssr/recap.md","filePath":"manual/computer-programming/ssr/recap.md"}'),s={name:"manual/computer-programming/ssr/recap.md"};function o(i,a,l,p,d,c){return r(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="收尾-·-决策树与常见坑" tabindex="-1">收尾 · 决策树与常见坑 <a class="header-anchor" href="#收尾-·-决策树与常见坑" aria-label="Permalink to &quot;收尾 · 决策树与常见坑&quot;">​</a></h1><p>用一张「什么页面选什么渲染 + 缓存策略」的决策树，和一份贯穿全专栏的「新手十大坑」清单，把 SSR 从入门到精通的全貌收拢。</p><p>走完这一路——CSR 的痛、SSR、水合、流式、服务端组件、边缘，再到整整八章缓存，最后到量化排查——是时候把一切收拢成两样能随手取用的东西：一张<strong>决策树</strong>，一份<strong>避坑清单</strong>。</p><h2 id="一张决策树-这个页面该怎么渲染-缓存" tabindex="-1">一张决策树：这个页面该怎么渲染 + 缓存 <a class="header-anchor" href="#一张决策树-这个页面该怎么渲染-缓存" aria-label="Permalink to &quot;一张决策树：这个页面该怎么渲染 + 缓存&quot;">​</a></h2><p>「精通 SSR」的核心，不是记住某个 API，而是<strong>为每个页面挑对策略</strong>。面对一个页面，顺着问下去：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;一个页面&quot;] --&gt; B{&quot;需要 SEO / 首屏快?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|&quot;否:后台 / 仪表盘&quot;| CSR[&quot;CSR&lt;br/&gt;(SEO 无关,交互频繁)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|&quot;是&quot;| C{&quot;内容对所有人相同?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt;|&quot;是&quot;| D{&quot;多久变一次?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt;|&quot;几乎不变:文档 / 博客&quot;| SSG[&quot;SSG&lt;br/&gt;(构建时生成,CDN 秒回)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt;|&quot;定期变,能容忍短暂旧&quot;| ISR[&quot;ISR / SWR&lt;br/&gt;(预生成 + 后台再生)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt;|&quot;否:个性化&quot;| E{&quot;能拆出共享大片?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt;|&quot;能&quot;| SHELL[&quot;静态壳 + 个性化补洞 / PPR&lt;br/&gt;(共享部分照缓存)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt;|&quot;强实时个性化&quot;| SSR[&quot;SSR + 数据缓存&lt;br/&gt;(每请求渲染,缓存贵数据)&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>这张树把整个专栏的取舍串成了一条可操作的路径。<strong>同一个站点的不同页面，落在不同的叶子上，是最优解、也是常态。</strong></p><h2 id="缓存分层速查" tabindex="-1">缓存分层速查 <a class="header-anchor" href="#缓存分层速查" aria-label="Permalink to &quot;缓存分层速查&quot;">​</a></h2><p>再把<a href="/Front2Full/manual/computer-programming/ssr/why-cache">缓存的四层关卡</a>按「离用户由近到远」收成一张表——排查和设计时对照着看：</p><table tabindex="0"><thead><tr><th>层</th><th>手段</th><th>关键旋钮</th><th>治什么</th></tr></thead><tbody><tr><td>浏览器</td><td>HTTP 缓存</td><td><code>max-age</code>、ETag</td><td>单用户重复访问</td></tr><tr><td>CDN / 边缘</td><td>共享缓存</td><td><code>s-maxage</code>、SWR、purge</td><td><strong>保护源站</strong>（最关键）</td></tr><tr><td>应用</td><td>数据缓存</td><td>Redis、<code>revalidate</code>、tags</td><td>省掉贵的取数</td></tr><tr><td>源站</td><td>渲染本身</td><td>流式、RSC、优化查询</td><td>未命中时的兜底成本</td></tr></tbody></table><h2 id="新手十大坑" tabindex="-1">新手十大坑 <a class="header-anchor" href="#新手十大坑" aria-label="Permalink to &quot;新手十大坑&quot;">​</a></h2><p>这十个坑，几乎每个上手 SSR 的人都踩过。记住它们，能省下大量深夜排查。</p><p><strong>① 水合失配。</strong> 渲染里用了 <code>Date.now()</code>、<code>window</code>、本地时区——服务端和客户端算出不一样，水合就炸。→ <a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a></p><p><strong>② <code>Set-Cookie</code> 悄悄关掉整站缓存。</strong> 某个中间件给每个响应都带上 <code>Set-Cookie</code>，CDN 于是全部 <code>BYPASS</code>，缓存形同虚设。排查缓存不生效，先看有没有多余的 <code>Set-Cookie</code>。→ <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">CDN 缓存</a></p><p><strong>③ <code>public</code> / <code>private</code> 用反。</strong> 个性化页错标 <code>public</code>，CDN 把「张三的页面」缓存下来发给李四——信息泄露。个性化必须 <code>private</code> / <code>no-store</code>。→ <a href="/Front2Full/manual/computer-programming/ssr/http-caching">HTTP 缓存</a></p><p><strong>④ <code>Vary: Cookie</code> 让命中率归零。</strong> 按 Cookie 分缓存 = 按用户分 = 无穷多份。→ <a href="/Front2Full/manual/computer-programming/ssr/http-caching">HTTP 缓存</a></p><p><strong>⑤ 缓存击穿。</strong> 热门页过期的刹那，千军万马同时回源打挂源站。→ 上 <a href="/Front2Full/manual/computer-programming/ssr/swr">SWR</a> / 请求合并。</p><p><strong>⑥ 忘了缓存失效。</strong> 数据早变了，页面还是旧的。→ <a href="/Front2Full/manual/computer-programming/ssr/cache-invalidation">按标签失效</a> + 长 TTL 兜底。</p><p><strong>⑦ TTL 和内容变化频率不匹配。</strong> 秒级变的数据缓存一小时（用户看到严重过期），或几乎不变的内容缓存 5 秒（白白频繁回源）。→ TTL 应匹配「内容真实的变化频率」。</p><p><strong>⑧ 无意义查询参数炸开缓存键。</strong> <code>?utm_source=...</code> 让同一页产生无数缓存键、命中率暴跌。→ 配 CDN 忽略追踪参数。→ <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">CDN 缓存</a></p><p><strong>⑨ 个性化过度，什么都缓存不了。</strong> 明明大部分内容共享，却因为一个「你好张三」把整页判成不可缓存。→ 拆共享 / 私有，或<a href="/Front2Full/manual/computer-programming/ssr/personalization">按人群段</a>降基数。</p><p><strong>⑩ 边缘离用户近，却离数据库远。</strong> 把渲染搬上边缘，却让它回中心查库，延迟又还回去了。→ 数据也上边缘 / 就近读缓存。→ <a href="/Front2Full/manual/computer-programming/ssr/edge-rendering">边缘渲染</a></p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>回到开篇那句话：<strong>SSR 的成败，九成在缓存。</strong> 走完这个专栏，你应该能体会到它的分量了——渲染本身（SSR、流式、RSC、边缘）决定了「能不能快、能不能被搜到」，而缓存（HTTP 头、CDN、SWR、ISR、数据缓存、失效、个性化）决定了「能不能扛、能不能省」。前者让 SSR <strong>可用</strong>，后者让 SSR <strong>可扩展</strong>。</p><p>更重要的是那套贯穿始终的思维方式：<strong>几乎没有银弹，每个方案都是一组权衡</strong>——新鲜度换扛量、速度换复杂度、缓存换一点点陈旧。「精通 SSR」不是背熟某个框架的 API，而是<strong>面对一个具体页面，能说清它该落在决策树的哪片叶子上、为什么、代价是什么</strong>。</p><p>框架会换，API 会变，但「何时渲染、在哪渲染、缓存哪一层、容忍多旧」这几个根本问题不会变。抓住它们，你就能看穿任何新框架的新名词——它们十有八九，只是这几个老问题的新答案。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] web.dev.「Rendering on the Web.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— 渲染策略决策的权威综述。</li><li>[2] Next.js 文档.「Rendering &amp; Caching.」<a href="https://nextjs.org/docs/app/building-your-application/rendering" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/rendering</a> —— 各策略与缓存的框架实现。</li><li>[3] MDN.「HTTP Caching.」<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching</a> —— 缓存机制的权威参考。</li></ul>`,28)])])}const h=t(s,[["render",o]]);export{u as __pageData,h as default};
